      background: linear-gradient(135deg, var(--primary), #7c3aed);
      box-shadow: 0 16px 34px rgba(79, 70, 229, 0.28);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      box-shadow: 0 20px 40px rgba(79, 70, 229, 0.34);
      transform: translateY(-1px);
    }

    button:active {
      transform: translateY(0);
    }

    .result {
      min-height: 1.5rem;
      margin: 0;
      color: var(--muted);
      font-weight: 700;
    }

    @media (max-width: 680px) {
      .quiz-card {
        padding: 24px;
        border-radius: 22px;
      }

      .form-field {
        padding: 20px;
      }

      .choices {
        grid-template-columns: 1fr;
      }

      .actions {
        align-items: stretch;
        flex-direction: column;
      }

      button {
        width: 100%;
      }
    }
  </style>
