<body>
  <main class="page">
    <section class="quiz-card" aria-labelledby="quiz-title">
      <p class="eyebrow">Multiple Select Quiz</p>
      <h1 id="quiz-title">Computer Languages</h1>
      <p class="intro">
        Pick every answer that applies for each question. Some questions may have more than one correct choice.
      </p>
      <div id="quiz-root"></div>
    </section>
  </main>

  <script>
    const questions = [
      {
        prompt: "Which of these are commonly used programming languages?",
        helpText: "Select all options that are programming languages rather than markup, query, or style languages.",
        choices: ["Python", "JavaScript", "CSS", "Ruby"]
      },
      {
        prompt: "Which languages are typically compiled before execution?",
        choices: ["C", "Rust", "HTML", "Go"]
      },
      {
        prompt: "Which languages are often used for web development?",
        choices: ["JavaScript", "TypeScript", "PHP", "Swift"]
      }
    ];

    function Choice({ questionIndex, choice }) {
      const id = `question-${questionIndex + 1}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

      return `
        <label class="choice" for="${id}">
          <input id="${id}" type="checkbox" name="question-${questionIndex + 1}" value="${choice}">
          <span>${choice}</span>
        </label>
      `;
    }

    function QuestionField({ question, index }) {
      const helpId = question.helpText ? `question-${index + 1}-help` : "";

      return `
        <div class="form-field">
          <fieldset ${helpId ? `aria-describedby="${helpId}"` : ""}>
            <div class="question-header">
              <span class="question-number" aria-hidden="true">${index + 1}</span>
              <div>
                <legend>${question.prompt}</legend>
                ${question.helpText ? `<p class="help-text" id="${helpId}">${question.helpText}</p>` : ""}
              </div>
            </div>
            <div class="choices">
              ${question.choices.map((choice) => Choice({ questionIndex: index, choice })).join("")}
            </div>
          </fieldset>
        </div>
      `;
    }

    function QuizApp({ questions }) {
      return `
        <form id="quiz-form">
          ${questions.map((question, index) => QuestionField({ question, index })).join("")}
          <div class="actions">
            <button type="submit">Submit answers</button>
            <p class="result" id="quiz-result" role="status" aria-live="polite"></p>
          </div>
        </form>
      `;
    }

    document.querySelector("#quiz-root").innerHTML = QuizApp({ questions });

    document.querySelector("#quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const answeredCount = questions.filter((_, index) => (
        document.querySelectorAll(`input[name="question-${index + 1}"]:checked`).length > 0
      )).length;

      document.querySelector("#quiz-result").textContent =
        `You answered ${answeredCount} of ${questions.length} questions.`;
    });
  </script>
