<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: light;
      --background: #f4f7fb;
      --surface: #ffffff;
      --surface-soft: #f8fafc;
      --text: #172033;
      --muted: #667085;
      --border: #d9e2ec;
      --primary: #4f46e5;
      --primary-dark: #4338ca;
      --ring: rgba(79, 70, 229, 0.18);
      --shadow: 0 24px 70px rgba(15, 23, 42, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(79, 70, 229, 0.14), transparent 34rem),
        linear-gradient(135deg, #eef2ff 0%, var(--background) 46%, #f8fafc 100%);
    }

    .page {
      display: grid;
      place-items: center;
      min-height: 100vh;
      padding: 48px 20px;
    }

    .quiz-card {
      width: min(100%, 820px);
      padding: 34px;
      border: 1px solid rgba(217, 226, 236, 0.78);
      border-radius: 28px;
      background: rgba(255, 255, 255, 0.9);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin: 0 0 14px;
      padding: 7px 12px;
      border-radius: 999px;
      color: var(--primary-dark);
      background: #eef2ff;
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3.4rem);
      line-height: 1.02;
      letter-spacing: -0.055em;
    }

    .intro {
      max-width: 620px;
      margin: 16px 0 30px;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.65;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      padding: 24px;
      border: 1px solid var(--border);
      border-radius: 22px;
      background: var(--surface);
      transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
    }

    .form-field:focus-within {
      border-color: rgba(79, 70, 229, 0.55);
      box-shadow: 0 0 0 6px var(--ring);
      transform: translateY(-1px);
    }

    .question-header {
      display: flex;
      gap: 14px;
      align-items: flex-start;
      margin-bottom: 16px;
    }

    .question-number {
      display: grid;
      flex: 0 0 auto;
      place-items: center;
      width: 36px;
      height: 36px;
      border-radius: 12px;
      color: #ffffff;
      background: linear-gradient(135deg, var(--primary), #7c3aed);
      font-weight: 800;
      box-shadow: 0 10px 24px rgba(79, 70, 229, 0.24);
    }

    legend {
      padding: 0;
      font-size: 1.1rem;
      font-weight: 800;
      line-height: 1.35;
    }

    fieldset {
      min-width: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    .help-text {
      margin: 8px 0 0;
      color: var(--muted);
      font-size: 0.94rem;
      line-height: 1.55;
    }

    .choices {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 12px;
      margin-top: 16px;
    }

    .choice {
      position: relative;
      display: flex;
      align-items: center;
      gap: 12px;
      min-height: 54px;
      padding: 14px 16px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: var(--surface-soft);
      color: #263249;
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, box-shadow 160ms ease;
    }

    .choice:hover {
      border-color: rgba(79, 70, 229, 0.48);
      background: #ffffff;
    }

    .choice input {
      width: 19px;
      height: 19px;
      margin: 0;
      accent-color: var(--primary);
    }

    .choice:has(input:checked) {
      border-color: rgba(79, 70, 229, 0.68);
      background: #eef2ff;
      box-shadow: inset 0 0 0 1px rgba(79, 70, 229, 0.08);
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      align-items: center;
      justify-content: space-between;
      margin-top: 6px;
      padding-top: 8px;
    }

    button {
      border: 0;
      border-radius: 16px;
      padding: 14px 22px;
      color: #ffffff;
      background: linear-gradient(135deg, var(--primary), #7c3aed);
      box-shadow: 0 16px 34px rgba(79, 70, 229, 0.28);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      box-shadow: 0 20px 40px rgba(79, 70, 229, 0.34);
      transform: translateY(-1px);
    }

    button:active {
      transform: translateY(0);
    }

    .result {
      min-height: 1.5rem;
      margin: 0;
      color: var(--muted);
      font-weight: 700;
    }

    @media (max-width: 680px) {
      .quiz-card {
        padding: 24px;
        border-radius: 22px;
      }

      .form-field {
        padding: 20px;
      }

      .choices {
        grid-template-columns: 1fr;
      }

      .actions {
        align-items: stretch;
        flex-direction: column;
      }

      button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="quiz-card" aria-labelledby="quiz-title">
      <p class="eyebrow">Multiple Select Quiz</p>
      <h1 id="quiz-title">Computer Languages</h1>
      <p class="intro">
        Pick every answer that applies for each question. Some questions may have more than one correct choice.
      </p>
      <form id="quiz-form" data-component="QuizApp">
        <div class="form-field" data-component="QuestionField">
          <fieldset aria-describedby="question-1-help">
            <div class="question-header">
              <span class="question-number" aria-hidden="true">1</span>
              <div>
                <legend>Which of these are commonly used programming languages?</legend>
                <p class="help-text" id="question-1-help">
                  Select all options that are programming languages rather than markup, query, or style languages.
                </p>
              </div>
            </div>
            <div class="choices">
              <label class="choice" data-component="Choice" for="question-1-python">
                <input id="question-1-python" type="checkbox" name="question-1" value="Python">
                <span>Python</span>
              </label>
              <label class="choice" data-component="Choice" for="question-1-javascript">
                <input id="question-1-javascript" type="checkbox" name="question-1" value="JavaScript">
                <span>JavaScript</span>
              </label>
              <label class="choice" data-component="Choice" for="question-1-css">
                <input id="question-1-css" type="checkbox" name="question-1" value="CSS">
                <span>CSS</span>
              </label>
              <label class="choice" data-component="Choice" for="question-1-ruby">
                <input id="question-1-ruby" type="checkbox" name="question-1" value="Ruby">
                <span>Ruby</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field" data-component="QuestionField">
          <fieldset>
            <div class="question-header">
              <span class="question-number" aria-hidden="true">2</span>
              <div>
                <legend>Which languages are typically compiled before execution?</legend>
              </div>
            </div>
            <div class="choices">
              <label class="choice" data-component="Choice" for="question-2-c">
                <input id="question-2-c" type="checkbox" name="question-2" value="C">
                <span>C</span>
              </label>
              <label class="choice" data-component="Choice" for="question-2-rust">
                <input id="question-2-rust" type="checkbox" name="question-2" value="Rust">
                <span>Rust</span>
              </label>
              <label class="choice" data-component="Choice" for="question-2-html">
                <input id="question-2-html" type="checkbox" name="question-2" value="HTML">
                <span>HTML</span>
              </label>
              <label class="choice" data-component="Choice" for="question-2-go">
                <input id="question-2-go" type="checkbox" name="question-2" value="Go">
                <span>Go</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field" data-component="QuestionField">
          <fieldset>
            <div class="question-header">
              <span class="question-number" aria-hidden="true">3</span>
              <div>
                <legend>Which languages are often used for web development?</legend>
              </div>
            </div>
            <div class="choices">
              <label class="choice" data-component="Choice" for="question-3-javascript">
                <input id="question-3-javascript" type="checkbox" name="question-3" value="JavaScript">
                <span>JavaScript</span>
              </label>
              <label class="choice" data-component="Choice" for="question-3-typescript">
                <input id="question-3-typescript" type="checkbox" name="question-3" value="TypeScript">
                <span>TypeScript</span>
              </label>
              <label class="choice" data-component="Choice" for="question-3-php">
                <input id="question-3-php" type="checkbox" name="question-3" value="PHP">
                <span>PHP</span>
              </label>
              <label class="choice" data-component="Choice" for="question-3-swift">
                <input id="question-3-swift" type="checkbox" name="question-3" value="Swift">
                <span>Swift</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit answers</button>
          <p class="result" id="quiz-result" role="status" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const quizQuestions = Array.from(document.querySelectorAll(".form-field"));

    document.querySelector("#quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const answeredCount = quizQuestions.filter((_, index) => (
        document.querySelectorAll(`input[name="question-${index + 1}"]:checked`).length > 0
      )).length;

      document.querySelector("#quiz-result").textContent =
        `You answered ${answeredCount} of ${quizQuestions.length} questions.`;
    });
  </script>
</body>
</html>
